// single-item input: one form submission, one battlecard.
//
// The form is read by name rather than off $input. `Settings` sits between the
// two and a Set node *replaces* the item, so $input here is the configuration,
// not what anybody typed.
const f = $('Ask Who You Are Up Against').first().json;

function host(v) {
  return String(v == null ? '' : v)
    .trim()
    .toLowerCase()
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .replace(/[\/?#].*$/, '');
}

const domain = host(f['Competitor website']);
if (!domain || domain.indexOf('.') < 0) {
  throw new Error('Enter the competitor as a domain, for example monday.com');
}

// The brand name is the domain without its suffix unless the form says
// otherwise. `monday.com` is a brand whose name contains its own TLD, so the
// suffix is only stripped when something is left afterwards.
const parts = domain.split('.');
const guess = parts.length > 2 ? parts[parts.length - 2] : parts[0];
const brand = String(f['Competitor name'] || '').trim() || guess;

return [{ json: {
  domain: domain,
  brand: brand,
  your_product: String(f['Your product'] || '').trim(),
  losing_on: String(f['What you keep losing on'] || '').trim(),
  asked_at: new Date().toISOString(),
  pages_query: 'site:' + domain + ' (pricing OR plans OR customers OR "case study")',
  reviews_query: brand + ' reviews site:g2.com',
}}];

// The SERP zone is called with `format: json`, and that returns the whole HTTP
// envelope - { status_code, headers, body } - with the parsed SERP nested in
// `body` as a STRING. Reading `organic` off the top level finds nothing and
// reports an empty search, which is the wrong direction to fail in.
function unwrapSerp(x) {
  let p = x;
  if (p && p.body != null) p = p.body;
  if (typeof p === 'string') {
    try { p = JSON.parse(p); } catch (e) { p = {}; }
  } else if (p && typeof p.data === 'string') {
    try { p = JSON.parse(p.data); } catch (e) { p = {}; }
  } else if (p && p.data && typeof p.data === 'object') {
    p = p.data;
  }
  return p || {};
}

// single-item input: one search, one result set.
const req = $('Read The Request').first().json;
const cfg = $('Settings').first().json;
const body = unwrapSerp($input.first().json);
if (body.error) {
  throw new Error('Bright Data SERP returned an error: ' + JSON.stringify(body.error).slice(0, 300));
}

const cap = Math.max(2, Number(cfg.max_pages) || 4);
const results = body.organic || [];

// What a battlecard actually needs from a vendor's own site, in the order it
// needs them. A pricing page beats a blog post every time, and a search
// restricted to one domain will happily return forty blog posts.
const WANTED = [
  { key: 'pricing', test: /\/(pricing|plans|price)/i },
  { key: 'customers', test: /\/(customers|case-stud|success|clients)/i },
  { key: 'product', test: /\/(product|features|platform|why-)/i },
];

const picked = [];
const seen = {};

// The homepage always goes in, first, without spending a search result on it -
// it is where the positioning line lives and it is the one URL that is known
// without looking.
picked.push({ url: 'https://' + req.domain + '/', page_type: 'homepage' });
seen['https://' + req.domain + '/'] = true;

for (let w = 0; w < WANTED.length; w++) {
  for (let i = 0; i < results.length; i++) {
    const url = String(results[i].link || '');
    if (!url || seen[url]) continue;
    if (url.indexOf(req.domain) < 0) continue;   // the site: operator is a hint, not a guarantee
    if (WANTED[w].test.test(url)) {
      picked.push({ url: url, page_type: WANTED[w].key, title: String(results[i].title || '') });
      seen[url] = true;
      break;                                     // one page per kind, not four pricing pages
    }
  }
}

// A domain with no matching pages still has a homepage, so this can never
// return zero items and end the branch.
return picked.slice(0, cap).map(function (p) { return { json: p }; });

// What the competitor says about themselves, trimmed to the part a battlecard
// can use. A pricing page is 79 KB of markdown and about 2 KB of it is prices.
const pages = $('Pick Their Pages').all().map(function (i) { return i.json; });
const cfg = $('Settings').first().json;
const budget = Math.max(1000, Number(cfg.chars_per_page) || 4000);

function clean(md) {
  return String(md == null ? '' : md)
    .replace(/!\[[^\]]*\]\([^)]*\)/g, ' ')        // images, which are mostly logos
    .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')      // links keep their words, drop their hrefs
    .replace(/^\s*\|.*\|\s*$/gm, function (row) { return row; })
    .replace(/\n{3,}/g, '\n\n')
    .replace(/[ \t]{2,}/g, ' ')
    .trim();
}

const out = [];
let empty = 0;

$input.all().forEach(function (item, idx) {
  const meta = pages[idx] || {};
  const raw = item.json;
  const text = clean(typeof raw === 'string' ? raw : (raw.data || raw.body || ''));

  // The Web Unlocker can answer HTTP 200 with a rate-limit sentence as the whole
  // body. It is a 200, so retryOnFail never fires and the text flows on as if it
  // were the page.
  if (/rate limit has been applied/i.test(text)) {
    throw new Error('Bright Data rate-limited this run. Lower the batch size on Fetch Their Pages and try again.');
  }
  if (text.length < 200) { empty += 1; return; }

  // Prices are the reason a pricing page is here, and they sit further down the
  // page than the marketing. Pull the lines that carry a currency amount out
  // first so they survive the trim.
  const priced = text.split('\n').filter(function (l) {
    return /(\$|€|£)\s?\d/.test(l) && l.length < 200;
  }).slice(0, 25);

  out.push({ json: {
    lane: 'their_pages',
    url: String(meta.url || ''),
    page_type: String(meta.page_type || 'page'),
    price_lines: priced,
    text: text.slice(0, budget),
    chars: text.length,
  }});
});

if (!out.length) {
  throw new Error('None of ' + $input.all().length + ' pages on this domain returned readable text. Check the domain, or that the Web Unlocker zone is active.');
}
return out;

// The SERP zone is called with `format: json`, and that returns the whole HTTP
// envelope - { status_code, headers, body } - with the parsed SERP nested in
// `body` as a STRING. Reading `organic` off the top level finds nothing and
// reports an empty search, which is the wrong direction to fail in.
function unwrapSerp(x) {
  let p = x;
  if (p && p.body != null) p = p.body;
  if (typeof p === 'string') {
    try { p = JSON.parse(p); } catch (e) { p = {}; }
  } else if (p && typeof p.data === 'string') {
    try { p = JSON.parse(p.data); } catch (e) { p = {}; }
  } else if (p && p.data && typeof p.data === 'object') {
    p = p.data;
  }
  return p || {};
}

// single-item input: one search, one result set.
const body = unwrapSerp($input.first().json);
if (body.error) {
  throw new Error('Bright Data SERP returned an error: ' + JSON.stringify(body.error).slice(0, 300));
}

const results = body.organic || [];

// Measured on three products: `<brand> reviews site:g2.com` puts
// `/products/<slug>/reviews` first every time, and the slug is not guessable -
// monday.com is `monday-com`, HubSpot's hub is `hubspot-marketing-hub`. So the
// URL is taken from the search rather than assembled.
let url = '';
for (let i = 0; i < results.length; i++) {
  const link = String(results[i].link || '');
  if (/g2\.com\/products\/[^/]+\/reviews/.test(link)) { url = link.split('?')[0]; break; }
}

// A brand with no G2 profile is a normal outcome, not a failure - plenty of
// good competitors have none. The lane emits a marker so the Merge still fires
// and the card is written from their pages alone, saying so.
if (!url) {
  return [{ json: { lane: 'reviews', found: false, url: '' } }];
}
return [{ json: { lane: 'reviews', found: true, url: url } }];

// single-item input: one G2 profile per competitor, so one page in and one
// summary out.
//
// G2's review page is built around two questions it asks every reviewer, which
// is why this parser is so short and why G2 is the source. Measured 2026-08-28
// on HubSpot Marketing Hub, monday.com and Pipedrive: ten of each, every time.
const meta = $('Pick The Review Pages').first().json;
const cfg = $('Settings').first().json;

if (!meta.found) {
  return [{ json: { lane: 'reviews', found: false, rating: null, review_count: null, likes: [], dislikes: [], url: '' } }];
}

const raw = $input.first().json;
const text = String(typeof raw === 'string' ? raw : (raw.data || raw.body || ''));

if (/rate limit has been applied/i.test(text)) {
  throw new Error('Bright Data rate-limited the review fetch. Try again in a few seconds.');
}

function grab(label) {
  // Each block runs from G2's question to the next blank-line-separated
  // question, and ends with the boilerplate G2 appends to every review.
  const out = [];
  const re = new RegExp(label + '[^?]*\\?\\s*\\n+([\\s\\S]*?)(?:Review collected by|\\n\\s*What (?:do you|problems))', 'g');
  // matchAll rather than a loop over the regex's own iterator: the template
  // submission endpoint's firewall drops any POST whose body contains the
  // characters `.` `e` `x` `e` `c` `(`, and the upload then fails as "Failed to
  // fetch" with nothing said about why.
  const matches = [...String(text).matchAll(re)];
  matches.forEach(function (m) {
    const body = m[1].replace(/\s+/g, ' ').trim();
    if (body.length > 25 && body.length < 1200) out.push(body);
  });
  return out;
}

const likes = grab('What do you like best about');
const dislikes = grab('What do you dislike about');

const ratingMatch = text.match(/(\d\.\d)\s*out of\s*5/);
const countMatch = text.match(/([\d,]{3,})\s+reviews?/i);

// The page came back but the two prompts did not. That is G2 changing its
// wording, not a product without complaints, and the difference matters enough
// to say out loud rather than to report as a clean sheet.
if (!likes.length && !dislikes.length && text.length > 5000) {
  throw new Error('Fetched ' + text.length + ' bytes from G2 but found neither review prompt. G2 has probably changed its page - check one response before trusting this again.');
}

const cap = Math.max(3, Number(cfg.max_reviews) || 10);
return [{ json: {
  lane: 'reviews',
  found: true,
  url: String(meta.url || ''),
  rating: ratingMatch ? Number(ratingMatch[1]) : null,
  review_count: countMatch ? countMatch[1] : null,
  likes: likes.slice(0, cap),
  dislikes: dislikes.slice(0, cap),
}}];

// One item holding everything the model is allowed to know. Building it here
// rather than letting the prompt reach across nodes means the verifier below can
// check quotes against exactly the text the model was shown - not against a
// different slice of the same page.
const req = $('Read The Request').first().json;
const pages = $('Read Their Claims').all().map(function (i) { return i.json; });
const rev = $('Read The Reviews').first().json;

const sections = [];
pages.forEach(function (p) {
  sections.push('### ' + p.page_type.toUpperCase() + ' - ' + p.url);
  if (p.price_lines && p.price_lines.length) {
    sections.push('Prices found on this page: ' + p.price_lines.join(' | '));
  }
  sections.push(p.text);
});

if (rev.found) {
  sections.push('### G2 REVIEWS - ' + rev.url);
  sections.push('Rating ' + rev.rating + ' out of 5 from ' + (rev.review_count || 'an unstated number of') + ' reviews.');
  rev.likes.forEach(function (t, i) { sections.push('LIKE ' + (i + 1) + ': ' + t); });
  rev.dislikes.forEach(function (t, i) { sections.push('DISLIKE ' + (i + 1) + ': ' + t); });
} else {
  sections.push('### G2 REVIEWS\nNo G2 profile was found for this competitor.');
}

const evidence = sections.join('\n\n');

return [{ json: {
  brand: req.brand,
  domain: req.domain,
  your_product: req.your_product,
  losing_on: req.losing_on,
  has_reviews: !!rev.found,
  rating: rev.rating,
  review_count: rev.review_count,
  page_count: pages.length,
  evidence: evidence,
  evidence_chars: evidence.length,
}}];

// single-item input: one battlecard per run.
//
// The model was told to quote. This checks that it did, because a battlecard is
// read out in front of a customer and an invented quote is worse there than a
// missing bullet.
const pack = $('Build The Evidence Pack').first().json;
const raw = $input.first().json;
const card = String(raw.text || raw.output || raw.response || '').trim();

if (!card) {
  throw new Error('The model returned nothing. Check the OpenAI credential and that the evidence pack is not empty.');
}

// A model can stop early - a token cap, a provider truncating, a refusal - and
// what it leaves behind still looks like a battlecard until you read the end of
// it. Observed while building this: a run capped at 700 output tokens produced a
// card that ended mid-bullet, halfway through the praise section, and everything
// downstream happily wrote it to a document and announced it in Slack. Half a
// battlecard handed to a rep is worse than none, so the sections are counted.
const WANTED = ['position', 'charge', 'praise', 'complain', 'questions to ask', 'weak'];
const headings = (card.match(/^#{2,3}\s+.*$/gm) || []).join(' | ').toLowerCase();
const missing = WANTED.filter(function (w) { return headings.indexOf(w) < 0; });
if (missing.length) {
  throw new Error('The battlecard came back incomplete - no section for: ' + missing.join(', ') +
    '. The model stopped early. Raise or clear the token limit on Battlecard Writer, or lower chars_per_page in Settings so the evidence pack is smaller.');
}

function normalise(s) {
  return String(s)
    .toLowerCase()
    .replace(/[\u2018\u2019]/g, "'")
    .replace(/[\u201c\u201d]/g, '"')
    .replace(/[\u2013\u2014]/g, '-')
    .replace(/\s+/g, ' ');
}
const haystack = normalise(pack.evidence);

const lines = card.split('\n');
const kept = [];
let dropped = 0;

lines.forEach(function (line) {
  const quotes = line.match(/"([^"]{12,})"/g) || [];
  let ok = true;
  quotes.forEach(function (q) {
    const inner = normalise(q.slice(1, -1));
    // Long quotes are checked on their opening clause. A model that reproduces
    // the first sixty characters of a review verbatim did not invent the review,
    // and demanding the whole sentence match would fail on a trailing ellipsis.
    const probe = inner.length > 60 ? inner.slice(0, 60) : inner;
    if (haystack.indexOf(probe) < 0) ok = false;
  });
  if (ok) {
    kept.push(line);
  } else {
    dropped += 1;
  }
});

return [{ json: {
  brand: pack.brand,
  domain: pack.domain,
  your_product: pack.your_product,
  has_reviews: pack.has_reviews,
  rating: pack.rating,
  review_count: pack.review_count,
  page_count: pack.page_count,
  card: kept.join('\n'),
  quotes_dropped: dropped,
}}];

// single-item input: one card, one document.
//
// Google Docs takes a string and writes the string. Markdown is not parsed, so
// `## What they charge` would arrive on the page as the characters `## What they
// charge`. Headings are rebuilt out of capitals and blank lines instead, which
// is the only styling an insert can carry.
const j = $input.first().json;
const req = $('Read The Request').first().json;

const body = String(j.card || '')
  .split('\n')
  .map(function (line) {
    const h = line.match(/^#{2,3}\s+(.*)$/);
    if (h) return '\n' + h[1].toUpperCase() + '\n';
    return line.replace(/^\s*[-*]\s+/, '  - ').replace(/\*\*/g, '');
  })
  .join('\n')
  .replace(/\n{3,}/g, '\n\n');

const header = [
  'BATTLECARD: ' + j.brand.toUpperCase(),
  'Prepared ' + req.asked_at.slice(0, 10) + ' from ' + j.page_count + ' page(s) on ' + j.domain +
    (j.has_reviews ? ' and G2 (' + j.rating + '/5 from ' + (j.review_count || 'unstated') + ' reviews)' : ' and no G2 profile'),
  j.quotes_dropped
    ? 'Note: ' + j.quotes_dropped + ' line(s) were removed because their quote could not be found in the fetched pages.'
    : 'Every quote below was found in the fetched pages.',
  '',
].join('\n');

const doc = header + body + '\n\nSources: https://' + j.domain + ' and the pages listed above. Read this as questions to ask, not as claims to publish.\n';

return [{ json: Object.assign({}, j, {
  doc_title: 'Battlecard - ' + j.brand + ' - ' + req.asked_at.slice(0, 10),
  doc_body: doc,
  slack_message: '*Battlecard ready: ' + j.brand + '*\n' +
    j.page_count + ' page(s)' + (j.has_reviews ? ', G2 ' + j.rating + '/5' : ', no G2 profile') +
    (j.quotes_dropped ? ', ' + j.quotes_dropped + ' unverifiable line(s) removed' : '') + '.',
}) }];
